// JobSeekerDashboard.js
import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';

const JobSeekerDashboard: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [jobSeeker, setJobSeeker] = useState<any>(null);

    useEffect(() => {
        const fetchJobSeeker = async () => {
            const response = await fetch(`http://localhost:8080/app/jobseeker/${id}`);
            if (response.ok) {
                const data = await response.json();
                setJobSeeker(data);
            } else {
                navigate('/login');
            }
        };

        fetchJobSeeker();
    }, [id, navigate]);

    const handleChatClick = () => {
        navigate('/chat-room');
    };

    return (
        <div className="container mt-5">
            <h1 className="text-center">Job Seeker Dashboard</h1>
            {jobSeeker && (
                <div>
                    <h4>Welcome, {jobSeeker.name}!</h4>
                    <h2>Your Agency Details</h2>
                    <p><strong>Agency Name:</strong> {jobSeeker.agency.name}</p>
                    {jobSeeker.agency.isApproved ? (
                        <div>
                            <button onClick={handleChatClick} className="btn btn-primary mt-3">
                                Start Chat
                            </button>
                            <div className="alert alert-success mt-3">
                                You have been confirmed by your agency. You can start chatting now!
                            </div>
                        </div>
                    ) : (
                        <p className="text-danger mt-3">Your agency is not approved for chat.</p>
                    )}
                </div>
            )}
        </div>
    );
};

export default JobSeekerDashboard;
